1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_RATE = 0.1;
3	const DEDUCTIBLE = 100;
4	const CAP_MULTIPLIER = 2;
5	
6	interface CatalogEntry {
7	  basePremium: number;
8	  insuranceValue: number;
9	}
10	
11	const CATALOG: Record<string, CatalogEntry> = {
12	  sword: { basePremium: 100, insuranceValue: 1000 },
13	  amulet: { basePremium: 60, insuranceValue: 600 },
14	  staff: { basePremium: 80, insuranceValue: 800 },
15	  potion: { basePremium: 40, insuranceValue: 400 },
16	  rune: { basePremium: 25, insuranceValue: 250 },
17	  moonstone: { basePremium: 25, insuranceValue: 250 },
18	};
19	
20	const basePremiumOf = (type: string): number => CATALOG[type]?.basePremium ?? 0;
21	const insuranceValueOf = (type: string): number => CATALOG[type]?.insuranceValue ?? 0;
22	
23	const sumBy = <T>(items: readonly T[], value: (item: T) => number): number =>
24	  items.reduce((total, item) => total + value(item), 0);
25	
26	interface Item {
27	  type: string;
28	  material?: string;
29	  enchantment?: number;
30	  cursed?: boolean;
31	}
32	
33	const HIGH_ENCHANTMENT_PREMIUM_THRESHOLD = 5;
34	
35	const enchantmentOf = (item: Item): number => item.enchantment ?? 0;
36	
37	const isCursed = (item: Item): boolean => item.cursed === true;
38	const hasHighEnchantmentForPremium = (item: Item): boolean =>
39	  enchantmentOf(item) >= HIGH_ENCHANTMENT_PREMIUM_THRESHOLD;
40	
41	const SURCHARGE_RATES: ReadonlyArray<{ applies: (item: Item) => boolean; rate: number }> = [
42	  { applies: isCursed, rate: 0.5 },
43	  { applies: hasHighEnchantmentForPremium, rate: 0.3 },
44	];
45	
46	const itemSurcharge = (item: Item): number =>
47	  basePremiumOf(item.type) *
48	  sumBy(SURCHARGE_RATES, ({ applies, rate }) => (applies(item) ? rate : 0));
49	
50	const itemsSurcharge = (items: Item[]): number => sumBy(items, itemSurcharge);
51	
52	interface QuoteStep {
53	  op: "quote";
54	  items: Item[];
55	}
56	
57	interface Damage {
58	  itemType: string;
59	  amount: number;
60	}
61	
62	interface ClaimStep {
63	  op: "claim";
64	  policy: number;
65	  incident: {
66	    cause: string;
67	    damages: Damage[];
68	  };
69	}
70	
71	type Step = QuoteStep | ClaimStep;
72	
73	interface Customer {
74	  yearsWithMHPCO: number;
75	}
76	
77	interface Scenario {
78	  customer: Customer;
79	  steps: Step[];
80	}
81	
82	interface QuoteResult {
83	  premium: number;
84	}
85	
86	interface ClaimResult {
87	  payout: number;
88	  remainingCap: number;
89	}
90	
91	type StepResult = QuoteResult | ClaimResult;
92	
93	interface ScenarioResult {
94	  results: StepResult[];
95	}
96	
97	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
98	const COMPONENT_BLOCK_SIZE = 3;
99	const COMPONENT_BLOCK_BASE = 60;
100	
101	const roundUpInMHPCOsFavor = (amount: number): number => Math.ceil(amount);
102	const roundDownInMHPCOsFavor = (amount: number): number => Math.floor(amount);
103	
104	const countItemsByType = (items: Item[]): Array<[string, number]> => {
105	  const counts = new Map<string, number>();
106	  for (const item of items) {
107	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
108	  }
109	  return [...counts];
110	};
111	
112	const isComponentBlock = (type: string, count: number): boolean =>
113	  COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE;
114	
115	const basePremiumForSameTypeItems = (type: string, count: number): number =>
116	  isComponentBlock(type, count) ? COMPONENT_BLOCK_BASE : basePremiumOf(type) * count;
117	
118	const itemsBasePremium = (items: Item[]): number =>
119	  sumBy(countItemsByType(items), ([type, count]) => basePremiumForSameTypeItems(type, count));
120	
121	const firstInsuranceSurcharge = (base: number): number => base * FIRST_INSURANCE_RATE;
122	
123	const LOYALTY_YEARS_THRESHOLD = 2;
124	const LOYALTY_DISCOUNT_RATE = 0.2;
125	
126	const isLoyalCustomer = (customer: Customer): boolean =>
127	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
128	
129	const loyaltyDiscount = (customer: Customer, base: number): number =>
130	  isLoyalCustomer(customer) ? base * LOYALTY_DISCOUNT_RATE : 0;
131	
132	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
133	
134	const followUpDiscount = (base: number, isFollowUp: boolean): number =>
135	  isFollowUp ? base * FOLLOW_UP_DISCOUNT_RATE : 0;
136	
137	const quotePremium = ({ items }: QuoteStep, customer: Customer, isFollowUp: boolean): number => {
138	  const base = itemsBasePremium(items);
139	  const premiumBeforeFee =
140	    base +
141	    itemsSurcharge(items) +
142	    firstInsuranceSurcharge(base) -
143	    loyaltyDiscount(customer, base) -
144	    followUpDiscount(base, isFollowUp);
145	  return roundUpInMHPCOsFavor(premiumBeforeFee + PROCESSING_FEE);
146	};
147	
148	interface Policy {
149	  items: Item[];
150	  remainingCap: number;
151	}
152	
153	const createPolicy = (step: QuoteStep): Policy => ({
154	  items: step.items,
155	  remainingCap: sumBy(step.items, (item) => insuranceValueOf(item.type)) * CAP_MULTIPLIER,
156	});
157	
158	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
159	const FULL_REIMBURSEMENT_RATE = 1;
160	const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
161	
162	const hasHighEnchantmentForClaim = (item: Item): boolean =>
163	  enchantmentOf(item) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD;
164	
165	const reimbursementRate = (item: Item): number =>
166	  hasHighEnchantmentForClaim(item) ? HIGH_ENCHANTMENT_REIMBURSEMENT_RATE : FULL_REIMBURSEMENT_RATE;
167	
168	const damagePayout = (damage: Damage, item: Item): number =>
169	  Math.max(0, damage.amount * reimbursementRate(item) - DEDUCTIBLE);
170	
171	const findItem = (policy: Policy, itemType: string): Item =>
172	  policy.items.find((item) => item.type === itemType)!;
173	
174	const calculatePayout = (damages: Damage[], policy: Policy): number => {
175	  const rawPayout = sumBy(damages, (damage) => damagePayout(damage, findItem(policy, damage.itemType)));
176	  return roundDownInMHPCOsFavor(Math.min(rawPayout, policy.remainingCap));
177	};
178	
179	const processClaim = (step: ClaimStep, policies: Map<number, Policy>): ClaimResult => {
180	  const policy = policies.get(step.policy)!;
181	  const payout = calculatePayout(step.incident.damages, policy);
182	  policy.remainingCap -= payout;
183	  return { payout, remainingCap: policy.remainingCap };
184	};
185	
186	const processQuote = (
187	  step: QuoteStep,
188	  customer: Customer,
189	  policies: Map<number, Policy>,
190	): QuoteResult => {
191	  const isFollowUp = policies.size > 0;
192	  policies.set(policies.size, createPolicy(step));
193	  return { premium: quotePremium(step, customer, isFollowUp) };
194	};
195	
196	const processStep = (
197	  step: Step,
198	  customer: Customer,
199	  policies: Map<number, Policy>,
200	): StepResult =>
201	  step.op === "quote"
202	    ? processQuote(step, customer, policies)
203	    : processClaim(step, policies);
204	
205	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => {
206	  const policies = new Map<number, Policy>();
207	  const results = steps.map((step) => processStep(step, customer, policies));
208	  return { results };
209	};
